// test_ref.c
// Portions of this file were generated by Claude.
// Checks against an independent double-precision model.
//   ./test_ref                 run all tests
//   ./test_ref --dump FILE     also write every case to a text file

// Allowed tolerance is 1e-5 * mag + 1e-30 (make #define insetad?)

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "dot_ref.h"

#define MAXNB 256

static FILE  *g_dump = NULL;
static int    g_cases = 0, g_fail = 0;
static double g_max_abs = 0.0, g_max_rel = 0.0;

// Common FP16 patterns
#define H_ONE   0x3C00  // 1.0
#define H_NEG1  0xBC00  // -1.0
#define H_HALF  0x3800  // 0.5
#define H_MAX   0x7BFF  // 65504
#define H_MINN  0x0400  // smallest normal, 2^-14
#define H_MIND  0x0001  // smallest denormal, 2^-24
#define H_DEN   0x03FF  // largest denormal
#define H_ZERO  0x0000

static uint32_t rng_state = 12345u;
static uint32_t rnd(void) {                       // xorshift32
    rng_state ^= rng_state << 13; rng_state ^= rng_state >> 17; rng_state ^= rng_state << 5;
    return rng_state;
}
static int8_t rnd_i8(void) { return (int8_t)(rnd() & 0xFF); }
// random finite FP16 with exponent field in [lo, hi], random sign
static ggml_fp16_t rnd_fp16(int lo, int hi) {
    uint16_t e = (uint16_t)(lo + rnd() % (hi - lo + 1));
    return (ggml_fp16_t)(((rnd() & 1) << 15) | (e << 10) | (rnd() & 0x3FF));
}

// Reference: exact integer sums, double-precision scales and accumulation
static void run_case(const char *name, int nb, const block_q8_0 *x, const block_q8_0 *y) {
    float got = 0.0f;
    ggml_vec_dot_q8_0_q8_0(nb * QK8_0, &got, 0, x, 0, y, 0, 1);

    double ref = 0.0, mag = 0.0;
    for (int i = 0; i < nb; i++) {
        long si = 0;
        for (int j = 0; j < QK8_0; j++) si += (long)x[i].qs[j] * y[i].qs[j];
        double t = (double)si * (double)fp16_to_fp32(x[i].d) * (double)fp16_to_fp32(y[i].d);
        ref += t; mag += fabs(t);
    }

    double abs_err = fabs((double)got - ref);
    double rel_err = (ref != 0.0) ? abs_err / fabs(ref) : (abs_err == 0.0 ? 0.0 : 1.0);
    // FP32 accumulation error scales with the sum of |terms|, not the final value
    int ok = abs_err <= 1e-5 * mag + 1e-30;

    g_cases++;
    if (!ok) {
        g_fail++;
        printf("FAIL %-28s nb=%3d got=%.9g ref=%.9g abs=%.3g rel=%.3g%%\n",
               name, nb, got, ref, abs_err, 100 * rel_err);
    }
    if (abs_err > g_max_abs) g_max_abs = abs_err;
    if (ok && rel_err > g_max_rel) g_max_rel = rel_err;

    if (g_dump) {   // line: nb | then per block: d_x qs_x[32] d_y qs_y[32] | expected float bits
        fprintf(g_dump, "%d", nb);
        for (int i = 0; i < nb; i++) {
            fprintf(g_dump, " %04x", x[i].d);
            for (int j = 0; j < QK8_0; j++) fprintf(g_dump, " %d", x[i].qs[j]);
            fprintf(g_dump, " %04x", y[i].d);
            for (int j = 0; j < QK8_0; j++) fprintf(g_dump, " %d", y[i].qs[j]);
        }
        uint32_t bits; memcpy(&bits, &got, 4);
        fprintf(g_dump, " %08x\n", bits);
    }
}

static void fill_const(block_q8_0 *b, int nb, ggml_fp16_t d, int8_t q) {
    for (int i = 0; i < nb; i++) { b[i].d = d; memset(b[i].qs, q, QK8_0); }
}

int main(int argc, char **argv) {
    if (argc == 3 && !strcmp(argv[1], "--dump")) g_dump = fopen(argv[2], "w");

    static block_q8_0 x[MAXNB], y[MAXNB];

    // ---- hand-chosen cases ----
    fill_const(x, 1, H_ONE, 1);   fill_const(y, 1, H_ONE, 1);   run_case("ones (expect 32)", 1, x, y);
    fill_const(x, 1, H_ONE, 0);   fill_const(y, 1, H_ONE, 57);  run_case("zero x", 1, x, y);
    fill_const(x, 1, H_ZERO, 5);  fill_const(y, 1, H_ONE, 5);   run_case("zero scale", 1, x, y);
    fill_const(x, 1, H_ONE, -128); fill_const(y, 1, H_ONE, -128); run_case("(-128)*(-128)", 1, x, y);
    fill_const(x, 1, H_ONE, -128); fill_const(y, 1, H_ONE, 127);  run_case("(-128)*127", 1, x, y);
    fill_const(x, 1, H_ONE, 127); fill_const(y, 1, H_NEG1, 127); run_case("negative scale", 1, x, y);
    fill_const(x, 1, H_HALF, 3);  fill_const(y, 1, H_HALF, 4);  run_case("scale 0.5*0.5", 1, x, y);
    fill_const(x, 8, H_ONE, -128); fill_const(y, 8, H_ONE, -128); run_case("max int accumulate", 8, x, y);

    // cancellation: alternating signs across blocks
    fill_const(x, 4, H_ONE, 100); fill_const(y, 4, H_ONE, 100);
    for (int i = 1; i < 4; i += 2) y[i].d = H_NEG1;
    run_case("block cancellation", 4, x, y);

    // scale extremes / denormals
    fill_const(x, 1, H_MAX, 127);  fill_const(y, 1, H_MAX, 127);  run_case("max scales", 1, x, y);
    fill_const(x, 1, H_MINN, 127); fill_const(y, 1, H_MINN, 127); run_case("min normal scales", 1, x, y);
    fill_const(x, 1, H_MIND, 127); fill_const(y, 1, H_ONE, 127);  run_case("denormal x scale (2^-24)", 1, x, y);
    fill_const(x, 1, H_DEN, 127);  fill_const(y, 1, H_DEN, 127);  run_case("largest denormal scales", 1, x, y);
    fill_const(x, 1, H_MIND, 1);   fill_const(y, 1, H_MIND, 1);   run_case("both smallest denormal", 1, x, y);

    // ramp pattern
    for (int j = 0; j < QK8_0; j++) { x[0].qs[j] = (int8_t)(j - 16); y[0].qs[j] = (int8_t)(2 * j - 31); }
    x[0].d = H_ONE; y[0].d = H_HALF;
    run_case("ramp", 1, x, y);

    // ---- random: full range, ordinary scales (2^-8 .. 2^1), many sizes ----
    int sizes[] = {1, 2, 3, 7, 16, 32, 64, 112, 128, 224};   // 224 blocks = 7168 elems
    for (size_t s = 0; s < sizeof sizes / sizeof *sizes; s++) {
        for (int t = 0; t < 50; t++) {
            for (int i = 0; i < sizes[s]; i++) {
                x[i].d = rnd_fp16(7, 16); y[i].d = rnd_fp16(7, 16);
                for (int j = 0; j < QK8_0; j++) { x[i].qs[j] = rnd_i8(); y[i].qs[j] = rnd_i8(); }
            }
            run_case("random", sizes[s], x, y);
        }
    }

    // ---- random: wide scale range including denormals and zero exponent ----
    for (int t = 0; t < 200; t++) {
        int nb = 1 + rnd() % 64;
        for (int i = 0; i < nb; i++) {
            x[i].d = rnd_fp16(0, 30); y[i].d = rnd_fp16(0, 30);
            for (int j = 0; j < QK8_0; j++) { x[i].qs[j] = rnd_i8(); y[i].qs[j] = rnd_i8(); }
        }
        run_case("random wide scales", nb, x, y);
    }

    // ---- random: small values, mimicking quantized LLM weights/activations ----
    for (int t = 0; t < 100; t++) {
        int nb = 64;
        for (int i = 0; i < nb; i++) {
            x[i].d = rnd_fp16(5, 12); y[i].d = rnd_fp16(5, 12);
            for (int j = 0; j < QK8_0; j++) { x[i].qs[j] = (int8_t)((int)(rnd() % 41) - 20); y[i].qs[j] = (int8_t)((int)(rnd() % 41) - 20); }
        }
        run_case("random small", nb, x, y);
    }

    if (g_dump) fclose(g_dump);
    printf("cases: %d  failed: %d\n", g_cases, g_fail);
    printf("max abs error: %.6g\n", g_max_abs);
    printf("max rel error: %.6g%%\n", 100 * g_max_rel);
    printf(g_fail ? "TEST FAILED\n" : "TEST PASSED\n");
    return g_fail ? 1 : 0;
}